const normalizado = $('03 - Normalizar | Datos de entrada').item.json;

// Mensaje original
let mensaje = normalizado.mensaje || '';

// Memoria recuperada desde Airtable
let memoria =
  $json.Resumen_Memoria ||
  $json.fields?.Resumen_Memoria ||
  'Cliente sin memoria previa.';

// Redactar emails
mensaje = mensaje.replace(
  /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,
  '[EMAIL REDACTADO]'
);

// Redactar posibles teléfonos
mensaje = mensaje.replace(
  /(?:\+?\d[\d\s\-()]{7,}\d)/g,
  '[TELEFONO REDACTADO]'
);

// Aplicar también a la memoria
memoria = memoria.replace(
  /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,
  '[EMAIL REDACTADO]'
);

memoria = memoria.replace(
  /(?:\+?\d[\d\s\-()]{7,}\d)/g,
  '[TELEFONO REDACTADO]'
);

return {
  json: {
    mensaje_saneado: mensaje.trim(),
    memoria_saneada: memoria.trim()
  }
};

